// SEQUENCE strategy — Hibernate pre-fetches a block of 50 ids → batching works
package com.bank.keys.model;

import jakarta.persistence.*;
import java.math.BigDecimal;

@Entity
@Table(name = "accounts")
public class Account {

    @Id
    @GeneratedValue(strategy = GenerationType.SEQUENCE, generator = "acc_seq")
    @SequenceGenerator(name = "acc_seq", sequenceName = "account_seq", allocationSize = 50)
    private Long id;

    @Column(name = "holder_name", nullable = false)
    private String holderName;

    private BigDecimal balance;

    protected Account() {}

    public Account(String holderName, BigDecimal balance) {
        this.holderName = holderName;
        this.balance = balance;
    }

    public Long getId() { return id; }
    public String getHolderName() { return holderName; }
    public BigDecimal getBalance() { return balance; }
}
```

