// ─── File: src/main/java/com/bank/keys/service/KeyGenService.java ───
package com.bank.keys.service;

import com.bank.keys.dto.KeyGenResult;
import com.bank.keys.model.Account;
import com.bank.keys.model.PaymentRef;
import com.bank.keys.repository.AccountRepository;
import com.bank.keys.repository.PaymentRefRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal;
import java.util.List;
import java.util.stream.IntStream;

@Service
@RequiredArgsConstructor
@Slf4j
public class KeyGenService {

    private final AccountRepository accountRepo;
    private final PaymentRefRepository paymentRepo;

    // SEQUENCE: block allocation of 50 ids → batched inserts, few round trips
    @Transactional
    public KeyGenResult createAccountsBatch(int count) {
        List<Account> accounts = IntStream.rangeClosed(1, count)
            .mapToObj(i -> new Account("Holder-" + i, new BigDecimal("10000")))
            .toList();
        accountRepo.saveAll(accounts);  // one sequence call serves 50 ids; inserts batch
        List<String> ids = accounts.stream().map(a -> String.valueOf(a.getId())).toList();
        log.info("[SEQUENCE] Created {} accounts; allocationSize=50 → ~{} sequence call(s)",
            count, Math.max(1, count / 50));
        return new KeyGenResult("SEQUENCE", ids,
            "Pre-fetched id block via account_seq (allocationSize=50) — batching enabled");
    }

    // UUID: id known BEFORE save, generated in the application
    @Transactional
    public KeyGenResult createPayment(BigDecimal amount, String payee) {
        PaymentRef ref = new PaymentRef(amount, payee);
        PaymentRef saved = paymentRepo.save(ref);
        log.info("[UUID] Payment ref id generated in app: {} (no DB round trip to obtain it)", saved.getId());
        return new KeyGenResult("UUID", List.of(saved.getId().toString()),
            "App-generated UUID — distribution friendly; prefer UUIDv7/ULID for clustered PK");
    }
}
