// ─── File: src/test/java/com/bank/keys/service/KeyGenTest.java ───
package com.bank.keys.service;

import com.bank.keys.model.Account;
import com.bank.keys.model.PaymentRef;
import org.junit.jupiter.api.Test;
import java.lang.reflect.Field;
import java.math.BigDecimal;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import static org.assertj.core.api.Assertions.*;

class KeyGenTest {

    @Test
    void accountUsesSequenceStrategy() throws Exception {
        Field idField = Account.class.getDeclaredField("id");
        GeneratedValue gv = idField.getAnnotation(GeneratedValue.class);
        assertThat(gv.strategy()).isEqualTo(GenerationType.SEQUENCE);
    }

    @Test
    void paymentUsesUuidStrategy() throws Exception {
        Field idField = PaymentRef.class.getDeclaredField("id");
        GeneratedValue gv = idField.getAnnotation(GeneratedValue.class);
        assertThat(gv.strategy()).isEqualTo(GenerationType.UUID);
    }

    @Test
    void identityWouldDisableBatching() {
        // IDENTITY needs each generated id immediately → Hibernate must flush per INSERT.
        // SEQUENCE pre-allocates a block → batch_size=50 works → far fewer round trips.
        int rows = 1000, allocationSize = 50;
        int sequenceCalls = rows / allocationSize;   // 20 calls serve 1000 ids
        assertThat(sequenceCalls).isEqualTo(20);
    }

    @Test
    void paymentRefConstructsWithoutIdYet() {
        // Before persistence the UUID is assigned by the provider; here we just show
        // the object is valid and the id is only set during save.
        PaymentRef ref = new PaymentRef(new BigDecimal("5000"), "Priya Sharma");
        assertThat(ref.getPayee()).isEqualTo("Priya Sharma");
    }
}
